"""
generate_training_data.py
=========================
Batch data generator for training a custom hybrid Judge model.

For each question it runs the full pipeline (asyncio-parallel where possible)
and saves a labelled row to SQLite:
    data/judge_training.db  →  table: training_samples

Resumable: already-processed questions are skipped automatically.
Crash-safe: every row is committed immediately after completion.

Estimated time: ~2-3 min per question × 2000 = 66–100 hours total.
Run in background:
    nohup python generate_training_data.py > training_log.txt 2>&1 &

Or just:
    python generate_training_data.py
"""

from __future__ import annotations

import os
import sys
os.environ.setdefault("KMP_DUPLICATE_LIB_OK", "TRUE")
os.environ.setdefault("PYTHONIOENCODING", "utf-8")

if sys.platform == "win32":
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
        sys.stderr.reconfigure(encoding="utf-8", errors="replace")
        import ctypes
        # ES_CONTINUOUS (0x80000000) | ES_SYSTEM_REQUIRED (0x00000001)
        # Prevents Windows OS from putting the PC to sleep while generating data,
        # while still allowing the screen/display to turn off safely.
        ctypes.windll.kernel32.SetThreadExecutionState(0x80000000 | 0x00000001)
    except Exception:
        pass

import asyncio
import random
import json
import re
import sqlite3
import time
from datetime import datetime
from pathlib import Path

from rich.console import Console
from rich.progress import (
    Progress, SpinnerColumn, TextColumn, BarColumn,
    MofNCompleteColumn, TimeElapsedColumn, TimeRemainingColumn,
)
from rich.table import Table
from rich import box

# ── Pipeline agents ───────────────────────────────────────────────────────────
