# ─────────────────────────────────────────────────────────────────────────────
# DATABASE SETUP
# ─────────────────────────────────────────────────────────────────────────────

def init_db(conn: sqlite3.Connection) -> None:
    conn.execute("PRAGMA journal_mode=WAL;")
    conn.execute("PRAGMA synchronous=NORMAL;")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS training_samples (
            id               INTEGER PRIMARY KEY AUTOINCREMENT,
            question         TEXT UNIQUE NOT NULL,
            answer_a         TEXT,
            answer_b         TEXT,
            verifier_text    TEXT,
            sem_sim_a        REAL,
            length_score_a   REAL,
            composite_a      REAL,
            word_count_a     INTEGER,
            sem_sim_b        REAL,
            length_score_b   REAL,
            composite_b      REAL,
            word_count_b     INTEGER,
            judge_raw        TEXT,
            factual_a        INTEGER,
            completeness_a   INTEGER,
            clarity_a        INTEGER,
            relevance_a      INTEGER,
            depth_a          INTEGER,
            total_a          INTEGER,
            factual_b        INTEGER,
            completeness_b   INTEGER,
            clarity_b        INTEGER,
            relevance_b      INTEGER,
            depth_b          INTEGER,
            total_b          INTEGER,
            winner           TEXT,
            final_answer     TEXT,
            elapsed_secs     REAL,
            created_at       TEXT
        )
    """)
    conn.commit()


def already_done(conn: sqlite3.Connection, question: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM training_samples WHERE question = ?", (question,)
    ).fetchone()
    return row is not None


def insert_row(conn: sqlite3.Connection, row: dict) -> None:
    conn.execute("""
        INSERT OR IGNORE INTO training_samples (
            question, answer_a, answer_b, verifier_text,
            sem_sim_a, length_score_a, composite_a, word_count_a,
            sem_sim_b, length_score_b, composite_b, word_count_b,
            judge_raw,
            factual_a, completeness_a, clarity_a, relevance_a, depth_a, total_a,
            factual_b, completeness_b, clarity_b, relevance_b, depth_b, total_b,
            winner, final_answer, elapsed_secs, created_at
        ) VALUES (
            :question, :answer_a, :answer_b, :verifier_text,
            :sem_sim_a, :length_score_a, :composite_a, :word_count_a,
            :sem_sim_b, :length_score_b, :composite_b, :word_count_b,
            :judge_raw,
            :factual_a, :completeness_a, :clarity_a, :relevance_a, :depth_a, :total_a,
            :factual_b, :completeness_b, :clarity_b, :relevance_b, :depth_b, :total_b,
            :winner, :final_answer, :elapsed_secs, :created_at
        )
    """, row)
    conn.commit()


# ─────────────────────────────────────────────────────────────────────────────
# JUDGE SCORE PARSER  — robust, handles varied Mistral output formatting
# ─────────────────────────────────────────────────────────────────────────────

def _split_into_sections(text: str) -> tuple[str, str]:
    """
    Split judge_text into (section_a, section_b).
    Handles both '## Answer 1' and plain 'Answer 1' section headers,
    with or without LLaMA/Mistral labels in parentheses.
    """
    # Try to find section-2 start first
    sep = re.search(
        r'(?:^|\n)\s*#{0,3}\s*Answer\s*2(?:\s*\(Mistral\))?\s*(?:\n|:)',
        text, re.IGNORECASE | re.MULTILINE
    )
    if sep:
        return text[:sep.start()], text[sep.start():]
    # Fallback: split at midpoint
    mid = len(text) // 2
    return text[:mid], text[mid:]


def _extract_score(chunk: str, label: str) -> int:
    """
    Find 'Label: N/10' or 'Label - N/10' or 'Label: N' in a text chunk.
    Very flexible — handles extra spaces, bolding (**), colons, dashes.
    """
    escaped = re.escape(label)
    patterns = [
        rf"{escaped}[\s:*-]+(\d{{1,2}})/10",      # "Clarity: 7/10"
        rf"{escaped}[\s:*-]+(\d{{1,2}})\s*out",   # "Clarity: 7 out of 10"
        rf"{escaped}[\s:*-]+Score[:\s]+(\d{{1,2}})", # "Clarity Score: 7"
        rf"{escaped}.*?(\d{{1,2}})/10",            # anything between, greedy
    ]
    for p in patterns:
        m = re.search(p, chunk, re.IGNORECASE)
        if m:
            val = int(m.group(1))
            if 0 <= val <= 10:
                return val
    return 0


def _extract_total(chunk: str) -> int:
    """Find TOTAL: XX/50 in a chunk, or compute sum of 5 criteria scores."""
    m = re.search(r"TOTAL[:\s*-]+(\d{1,2})/50", chunk, re.IGNORECASE)
    if m:
        val = int(m.group(1))
        if 0 <= val <= 50:
            return val
    # Compute from individual scores as fallback
    total = sum([
        _extract_score(chunk, "Factual Accuracy"),
        _extract_score(chunk, "Completeness"),
        _extract_score(chunk, "Clarity"),
        _extract_score(chunk, "Relevance"),
        _extract_score(chunk, "Depth of Reasoning"),
    ])
    return total


def _extract_winner(text: str) -> str:
    """Find winner declaration — handles various phrasings."""
    patterns = [
        r"Winner[:\s*-]+Answer\s*(1|2)",
        r"Winner[:\s*-]+(?:Answer\s*)?(LLaMA|Llama|llama)",   # → A
        r"Winner[:\s*-]+(?:Answer\s*)?(Mistral|mistral)",      # → B
        r"(?:better|superior|wins)[\s\w]*?(?:Answer|LLM)\s*(1|2)",
        r"Answer\s*(1|2)\s+(?:is the winner|wins)",
    ]
    for p in patterns:
        m = re.search(p, text, re.IGNORECASE)
        if m:
            raw = m.group(1) if m.lastindex else ''
            if raw in ('1', 'LLaMA', 'Llama', 'llama', ''):
                return 'A'
            if raw in ('2', 'Mistral', 'mistral'):
                return 'B'
    return 'unknown'


def resolve_winner_tie_break(
    winner: str,
    total_a: int, total_b: int,
    factual_a: int, factual_b: int,
    depth_a: int, depth_b: int,
    completeness_a: int, completeness_b: int,
    clarity_a: int, clarity_b: int,
    relevance_a: int, relevance_b: int,
    word_count_a: int, word_count_b: int,
    question: str
) -> str:
    """Apply strict, deterministic tie-breaking rules to guarantee a winner A or B."""
    # 1. Total Score comparison (highest score wins)
    if total_a > total_b:
        return 'A'
    if total_b > total_a:
        return 'B'

    # If scores are equal, apply tie-breaker hierarchy:
    # 2. Factual Accuracy
    if factual_a != factual_b:
        return 'A' if factual_a > factual_b else 'B'

    # 3. Depth of Reasoning
    if depth_a != depth_b:
        return 'A' if depth_a > depth_b else 'B'

    # 4. Completeness
    if completeness_a != completeness_b:
        return 'A' if completeness_a > completeness_b else 'B'

    # 5. Clarity
    if clarity_a != clarity_b:
        return 'A' if clarity_a > clarity_b else 'B'

    # 6. Relevance
    if relevance_a != relevance_b:
        return 'A' if relevance_a > relevance_b else 'B'

    # 7. Word Count / Conciseness (Shorter answer wins, penalizing verbosity)
    if word_count_a != word_count_b:
        if word_count_a == 0:
            return 'B'
        if word_count_b == 0:
            return 'A'
        return 'A' if word_count_a < word_count_b else 'B'

    # 8. Absolute Deterministic Fallback (Hash of the question)
    import binascii
    h = binascii.crc32(question.encode('utf-8'))
    return 'A' if h % 2 == 0 else 'B'


def parse_judge_scores(
    judge_text: str,
    question: str = "",
    answer_a: str = "",
    answer_b: str = ""
) -> dict:
    """Parse structured judge output into numeric fields, resolving ties strictly."""
    sec_a, sec_b = _split_into_sections(judge_text)

    result: dict = {}
    for side, chunk in (('a', sec_a), ('b', sec_b)):
        result[f"factual_{side}"]      = _extract_score(chunk, "Factual Accuracy")
        result[f"completeness_{side}"] = _extract_score(chunk, "Completeness")
        result[f"clarity_{side}"]      = _extract_score(chunk, "Clarity")
        result[f"relevance_{side}"]    = _extract_score(chunk, "Relevance")
        result[f"depth_{side}"]        = _extract_score(chunk, "Depth of Reasoning")
        result[f"total_{side}"]        = _extract_total(chunk)

    winner = _extract_winner(judge_text)
    
    # Calculate word counts for conciseness tie-breaking
    word_count_a = len(answer_a.split()) if answer_a else 0
    word_count_b = len(answer_b.split()) if answer_b else 0

    result["winner"] = resolve_winner_tie_break(
        winner,
        result["total_a"], result["total_b"],
        result["factual_a"], result["factual_b"],
        result["depth_a"], result["depth_b"],
        result["completeness_a"], result["completeness_b"],
        result["clarity_a"], result["clarity_b"],
        result["relevance_a"], result["relevance_b"],
        word_count_a, word_count_b,
        question
    )
    return result


# ─────────────────────────────────────────────────────────────────────────────
# ASYNC PIPELINE  (mirrors server.py parallelism)
# ─────────────────────────────────────────────────────────────────────────────

async def run_pipeline_async(query: str) -> dict:
    """Run the full pipeline and return a flat dict ready for DB insertion."""
    t0 = time.time()

    # Initialise all agents (lightweight, just creates LangChain objects)
    llama3_agent   = create_llama3_agent()
    mistral_agent  = create_mistral_agent()
    verifier_agent = create_verifier_agent()
    judge_agent    = create_judge_agent()
    combiner_agent = create_combiner_agent()

    llama_prompt = (
        f"Answer the following question thoroughly and accurately.\n\n"
        f"Question: {query}\n\n"
        f"Provide a well-structured, comprehensive answer of at most 350 words. "
        f"Use clear language, headings, or bullet points where appropriate."
    )
    mistral_prompt = (
        f"Answer the following question thoroughly and accurately.\n\n"
        f"Question: {query}\n\n"
        f"Provide a well-structured, comprehensive answer of at most 350 words. "
        f"Include practical examples and unique insights."
    )

    # Stage 1+2: parallel generation
    loop = asyncio.get_event_loop()
    answer_a, answer_b = await asyncio.gather(
        loop.run_in_executor(None, lambda: llama3_agent.run(llama_prompt)),
        loop.run_in_executor(None, lambda: mistral_agent.run(mistral_prompt)),
    )

    # 50/50 Position Swap Randomization (eliminates order preference bias)
    swapped = random.choice([True, False])
    eval_ans_1, eval_ans_2 = (answer_b, answer_a) if swapped else (answer_a, answer_b)

    # Stage 3+4: parallel verification + scoring
    verifier_prompt = build_verifier_prompt(query, eval_ans_1, eval_ans_2)
    verifier_text, scores_tuple = await asyncio.gather(
        loop.run_in_executor(None, lambda: verifier_agent.run(verifier_prompt)),
        loop.run_in_executor(None, lambda: (
            score_response(query, answer_a),
            score_response(query, answer_b),
        )),
    )
    scores_a, scores_b = scores_tuple

    # Stage 5: judge
    judge_prompt = build_judge_prompt(query, eval_ans_1, eval_ans_2)
    judge_raw = await loop.run_in_executor(None, lambda: judge_agent.run(judge_prompt))

    # Stage 6: combiner
    combiner_prompt = build_combiner_prompt(
        query, eval_ans_1, eval_ans_2, verifier_text, judge_raw
    )
    final_answer = await loop.run_in_executor(
        None, lambda: combiner_agent.run(combiner_prompt)
    )

    elapsed = time.time() - t0

    # Parse scores (account for position swap)
    if swapped:
        parsed = parse_judge_scores(judge_raw, query, answer_b, answer_a)
        raw_winner = parsed["winner"]
        real_winner = "B" if raw_winner == "A" else ("A" if raw_winner == "B" else "unknown")
        
        parsed["factual_a"], parsed["factual_b"] = parsed["factual_b"], parsed["factual_a"]
        parsed["completeness_a"], parsed["completeness_b"] = parsed["completeness_b"], parsed["completeness_a"]
        parsed["clarity_a"], parsed["clarity_b"] = parsed["clarity_b"], parsed["clarity_a"]
        parsed["relevance_a"], parsed["relevance_b"] = parsed["relevance_b"], parsed["relevance_a"]
        parsed["depth_a"], parsed["depth_b"] = parsed["depth_b"], parsed["depth_a"]
        parsed["total_a"], parsed["total_b"] = parsed["total_b"], parsed["total_a"]
        parsed["winner"] = real_winner
    else:
        parsed = parse_judge_scores(judge_raw, query, answer_a, answer_b)

    return {
        "question":       query,
        "answer_a":       answer_a,
        "answer_b":       answer_b,
        "verifier_text":  verifier_text,
        "sem_sim_a":      scores_a["semantic_similarity"],
        "length_score_a": scores_a["length_score"],
        "composite_a":    scores_a["composite_score"],
        "word_count_a":   scores_a["word_count"],
        "sem_sim_b":      scores_b["semantic_similarity"],
        "length_score_b": scores_b["length_score"],
        "composite_b":    scores_b["composite_score"],
        "word_count_b":   scores_b["word_count"],
        "judge_raw":      judge_raw,
        **parsed,
        "final_answer":   final_answer,
        "elapsed_secs":   elapsed,
        "created_at":     datetime.now().isoformat(),
    }


# ─────────────────────────────────────────────────────────────────────────────
# MAIN LOOP
# ─────────────────────────────────────────────────────────────────────────────

async def main() -> None:
    console.rule("[bold yellow]Judge Training Data Generator (High-GPU Concurrency)[/bold yellow]")
    CONCURRENCY = 2
    console.print(f"[dim]Target: {len(QUESTIONS)} questions  |  DB: {DB_PATH}  |  GPU Parallel Concurrency: {CONCURRENCY} workers[/dim]\n")

    conn = sqlite3.connect(str(DB_PATH), timeout=60.0)
    init_db(conn)

    # Count already done
    done_count = conn.execute("SELECT COUNT(*) FROM training_samples").fetchone()[0]
    console.print(f"[green]Resuming from {done_count} already completed rows.[/green]\n")

    success = 0
    failed  = 0
    db_lock = asyncio.Lock()
    sem     = asyncio.Semaphore(CONCURRENCY)

    log_file_path = Path(__file__).parent / "training_log.txt"

    with Progress(
        SpinnerColumn(),
        TextColumn("[bold cyan]{task.description}[/bold cyan]"),
        BarColumn(),
        MofNCompleteColumn(),
        TimeElapsedColumn(),
        TimeRemainingColumn(),
        console=console,
        refresh_per_second=4,
    ) as progress:
        task = progress.add_task("Generating...", total=len(QUESTIONS))
        progress.advance(task, advance=done_count)  # start at already-done count

        async def process_one(i: int, question: str) -> None:
            nonlocal success, failed
            async with db_lock:
                if already_done(conn, question):
                    progress.advance(task, advance=1)
                    return

            async with sem:
                progress.update(task, description=f"[{i}/{len(QUESTIONS)}] {question[:60]}…")
                try:
                    row = await run_pipeline_async(question)
                    async with db_lock:
                        insert_row(conn, row)
                        success += 1
                        msg = (
                            f"  + [{i}] {question[:55]}... "
                            f"({row['elapsed_secs']:.0f}s | winner={row['winner']} | "
                            f"A={row['total_a']}/50 B={row['total_b']}/50)"
                        )
                        console.print(msg)
                        with open(log_file_path, "a", encoding="utf-8") as lf:
                            lf.write(msg + "\n")
                            lf.flush()
                except Exception as exc:
                    async with db_lock:
                        failed += 1
                        err_msg = f"  x [{i}] {question[:55]}... ERROR: {exc}"
                        console.print(err_msg)
                        with open(log_file_path, "a", encoding="utf-8") as lf:
                            lf.write(err_msg + "\n")
                            lf.flush()
                finally:
                    progress.advance(task, advance=1)

        tasks = [process_one(i, q) for i, q in enumerate(QUESTIONS, start=1)]
        await asyncio.gather(*tasks)

    conn.close()

    # Summary table
    table = Table(title="[bold]Generation Complete[/bold]", box=box.ROUNDED)
    table.add_column("Metric", style="bold")
    table.add_column("Count", justify="right")
    table.add_row("Total questions",  str(len(QUESTIONS)))
    table.add_row("Successful rows",  f"[green]{success}[/green]")
    table.add_row("Failed / skipped", f"[red]{failed}[/red]")
    table.add_row("DB path", str(DB_PATH))
    console.print(table)
    console.print(f"\n[bold green]Dataset saved to:[/bold green] {DB_PATH}\n")


if __name__ == "__main__":
    asyncio.run(main())
